"""
NABBAH — حزمة المحركات في ملف واحد (بديل عن مجلدات phase21 / phase22 / phase23).

ضع هذا الملف بجانب main.py مباشرة. عند استيراده يسجّل كل المحركات في الذاكرة،
فتعمل أوامر مثل: import scenario_engine

المصدر واحد: نفس ملفات المجلدات حرفياً، مُضمَّنة هنا بترميز base64 لتفادي مشاكل
رفع المجلدات. لا يوجد أي منطق جديد.
"""
import base64
import sys
import types

_MODULES = [
    ("nabbah_finance", ""),
    ("nabbah_trust", ""),
    ("period_aggregation", ""),
    ("legacy_adapters", ""),
    ("semantic_layer", ""),
    ("kpi_engine", ""),
    ("analysis_engines", ""),
    ("ai_gateway", ""),
    ("rule_catalog", ""),
    ("forecast_engine", ""),
    ("intelligence_engine", ""),
    ("decision_memory", ""),
    ("scenario_engine", ""),
    ("platform_bridge", ""),
]

_loaded = []
for _name, _b64 in _MODULES:
    if _name in sys.modules:
        _loaded.append(_name)
        continue
    _mod = types.ModuleType(_name)
    _mod.__file__ = f"<nabbah_engines:{_name}>"
    sys.modules[_name] = _mod
    try:
        exec(compile(base64.b64decode(_b64).decode("utf-8"), _mod.__file__, "exec"), _mod.__dict__)
        _loaded.append(_name)
    except Exception:
        del sys.modules[_name]
        raise

LOADED = tuple(_loaded)
